INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Trennt eine Subnetzmaske den Netzwerk- vom Host-Teil einer IPv4-Adresse?', 2, '[{"text": "Ja", "correct": true, "because": "Die Subnetzmaske definiert, welche Bits das Netzwerk identifizieren"}, {"text": "Nein", "correct": false, "because": "Das ist die Hauptfunktion der Subnetzmaske"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist 255.255.255.0 eine gültige Subnetzmaske für ein IPv4-Netzwerk?', 2, '[{"text": "Ja", "correct": true, "because": "Entspricht /24 und ist eine Standardmaske"}, {"text": "Nein", "correct": false, "because": "Es ist eine häufig genutzte Maske"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Subnetzmaske weniger als 8 Bits für das Netzwerk verwenden?', 2, '[{"text": "Ja", "correct": true, "because": "z. B. /7 ist möglich, aber selten"}, {"text": "Nein", "correct": false, "because": "Kleinere Masken sind technisch erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine Subnetzmaske immer durchgehende Einsen enthalten?', 2, '[{"text": "Ja", "correct": true, "because": "Subnetzmasken müssen kontinuierlich sein (z. B. 255.255.0.0)"}, {"text": "Nein", "correct": false, "because": "Nicht-kontinuierliche Masken sind ungültig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Subnetzmaske 255.255.255.255 für ein Netzwerk mit mehreren Hosts sinnvoll?', 2, '[{"text": "Nein", "correct": true, "because": "/32 lässt nur eine Adresse zu (kein Hostbereich)"}, {"text": "Ja", "correct": false, "because": "Es bleibt kein Platz für Hosts"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Subnetzmaske entspricht der CIDR-Notation /24?', 2, '[{"text": "255.255.255.0", "correct": true, "because": "24 Bits = 255.255.255.0"}, {"text": "255.255.0.0", "correct": false, "because": "Das ist /16"}, {"text": "255.0.0.0", "correct": false, "because": "Das ist /8"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Hosts sind in einem Netzwerk mit der Subnetzmaske 255.255.255.240 möglich?', 3, '[{"text": "14", "correct": true, "because": "/28 = 2^(32-28) - 2 = 14 Hosts"}, {"text": "30", "correct": false, "because": "Das wäre /27"}, {"text": "6", "correct": false, "because": "Das wäre /29"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Subnetzmaske gehört standardmäßig zur Klasse C?', 2, '[{"text": "255.255.255.0", "correct": true, "because": "Klasse C hat 24 Netzwerkbits"}, {"text": "255.255.0.0", "correct": false, "because": "Das ist Klasse B"}, {"text": "255.0.0.0", "correct": false, "because": "Das ist Klasse A"}]'),
('00000000-0000-0000-0000-000000000000', 'Was bedeutet eine Subnetzmaske von 255.255.255.252?', 2, '[{"text": "2 Hosts pro Subnetz", "correct": true, "because": "/30 = 2^(32-30) - 2 = 2 Hosts"}, {"text": "4 Hosts pro Subnetz", "correct": false, "because": "Das wäre /29"}, {"text": "254 Hosts pro Subnetz", "correct": false, "because": "Das wäre /24"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Subnetzmaske erlaubt die meisten Hosts in einem IPv4-Netzwerk?', 2, '[{"text": "255.0.0.0", "correct": true, "because": "/8 = 2^24 - 2 Hosts"}, {"text": "255.255.0.0", "correct": false, "because": "Weniger Hosts als /8"}, {"text": "255.255.255.0", "correct": false, "because": "Nur 254 Hosts"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Subnetzmasken sind gültig für IPv4?', 4, '[{"text": "255.255.255.0", "correct": true, "because": "Entspricht /24"}, {"text": "255.255.240.0", "correct": true, "because": "Entspricht /20"}, {"text": "255.255.255.1", "correct": false, "because": "Nicht kontinuierlich"}, {"text": "255.255.255.192", "correct": true, "because": "Entspricht /26"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat die Subnetzmaske 255.255.255.128?', 3, '[{"text": "CIDR-Notation /25", "correct": true, "because": "25 Netzwerkbits"}, {"text": "126 Hosts möglich", "correct": true, "because": "2^(32-25) - 2 = 126"}, {"text": "Nur für Klasse A geeignet", "correct": false, "because": "Flexibel einsetzbar"}, {"text": "2 Subnetze aus /24", "correct": true, "because": "Teilt /24 in zwei Netze"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn die Subnetzmaske von /24 auf /26 geändert wird?', 4, '[{"text": "Weniger Hosts pro Subnetz", "correct": true, "because": "Von 254 auf 62 Hosts"}, {"text": "Mehr Subnetze möglich", "correct": true, "because": "4 Subnetze statt 1"}, {"text": "Netzwerkgröße bleibt gleich", "correct": false, "because": "Subnetze werden kleiner"}, {"text": "Hostbereich schrumpft", "correct": true, "because": "Weniger verfügbare Adressen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Subnetzmasken könnten für ein Netzwerk mit 10 Hosts verwendet werden?', 3, '[{"text": "255.255.255.240", "correct": true, "because": "/28 = 14 Hosts, passt"}, {"text": "255.255.255.248", "correct": false, "because": "/29 = 6 Hosts, zu klein"}, {"text": "255.255.255.224", "correct": true, "because": "/27 = 30 Hosts, passt"}, {"text": "255.255.255.252", "correct": false, "because": "/30 = 2 Hosts, zu klein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aussagen über die Subnetzmaske sind korrekt?', 3, '[{"text": "Definiert den Netzwerkteil", "correct": true, "because": "Trennt Netzwerk von Host"}, {"text": "Muss binär kontinuierlich sein", "correct": true, "because": "Keine Lücken erlaubt"}, {"text": "Kann beliebige Werte haben", "correct": false, "because": "Nur bestimmte Werte gültig"}, {"text": "Wird in CIDR als Schrägstrich angegeben", "correct": true, "because": "z. B. /24"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Subnetzmaske 255.255.255.0 erlaubt 254 Hosts. b) /32 ist für Subnetze mit mehreren Hosts geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "/24 = 254 Hosts, /32 nur 1 Adresse"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Subnetzmaske von /16 entspricht 255.255.0.0. b) /24 erlaubt mehr Subnetze als /22.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "/16 ist 255.255.0.0, /24 hat weniger Subnetze als /22"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Subnetzmaske teilt ein Netzwerk in Subnetze. b) 255.255.255.254 erlaubt 2 Hosts.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Subnetzmaske teilt, aber /31 hat 0 Hosts"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch (255.255.255.254 ist /31)"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) /26 hat 62 Hosts pro Subnetz. b) /30 ist für Punkt-zu-Punkt-Verbindungen geeignet.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "/26 = 62 Hosts, /30 = 2 Hosts, ideal für P2P"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Subnetzmaske 255.255.255.192 teilt ein /24-Netz in 4 Subnetze. b) /8 ist nur für kleine Netzwerke geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "/26 = 4 Subnetze aus /24, /8 für große Netze"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

